import{_ as e,o as s,c as t,ag as n}from"./chunks/framework.NkeMC67b.js";const d=JSON.parse('{"title":"Support","description":"Get help with Sikshya — WordPress.org forum, GitHub bug reports, the Facebook community, Pro priority support, and how to file a useful bug report.","frontmatter":{"title":"Support","description":"Get help with Sikshya — WordPress.org forum, GitHub bug reports, the Facebook community, Pro priority support, and how to file a useful bug report."},"headers":[],"relativePath":"support.md","filePath":"support.md","lastUpdated":1778327862000}'),r={name:"support.md"};function o(i,a,l,p,c,u){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h1><p>Sikshya is supported in four places, depending on what you need.</p><h2 id="where-to-ask" tabindex="-1">Where to ask <a class="header-anchor" href="#where-to-ask" aria-label="Permalink to &quot;Where to ask&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>Best for</th><th>Response</th></tr></thead><tbody><tr><td><a href="https://wordpress.org/support/plugin/sikshya/" target="_blank" rel="noreferrer">WordPress.org plugin forum</a></td><td>Public Q&amp;A on the free plugin</td><td>Best effort</td></tr><tr><td><a href="https://www.facebook.com/groups/sikshyalms/" target="_blank" rel="noreferrer">Sikshya LMS Facebook Community</a></td><td>Peer discussion + tips</td><td>Peer-led</td></tr><tr><td><a href="https://github.com/MantraBrain" target="_blank" rel="noreferrer">GitHub issues</a></td><td>Bug reports, feature requests, code-level talk</td><td>Best effort</td></tr><tr><td><a href="https://mantrabrain.com/contact/" target="_blank" rel="noreferrer">Mantrabrain priority support</a></td><td>Pro license holders, billing, urgent issues</td><td>Per plan SLA</td></tr></tbody></table><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Priority support is included with every Pro plan</span></div><p class="pro-callout__desc">Pro license holders get faster response times via the priority queue. Severity-1 (&quot;site down&quot;) tickets are escalated.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Compare Pro plans →</a></div><h2 id="filing-a-useful-bug-report" tabindex="-1">Filing a useful bug report <a class="header-anchor" href="#filing-a-useful-bug-report" aria-label="Permalink to &quot;Filing a useful bug report&quot;">​</a></h2><p>A good bug report saves a round-trip and gets your issue fixed faster. Include:</p><h3 id="_1-environment" tabindex="-1">1. Environment <a class="header-anchor" href="#_1-environment" aria-label="Permalink to &quot;1. Environment&quot;">​</a></h3><ul><li>WordPress version (<span class="screen-path">Settings → General</span>).</li><li>PHP version (<span class="screen-path">Tools → Site Health → Info</span>).</li><li>Sikshya version + Sikshya Pro version.</li><li>Active theme.</li><li>Active plugins list.</li></ul><h3 id="_2-steps-to-reproduce" tabindex="-1">2. Steps to reproduce <a class="header-anchor" href="#_2-steps-to-reproduce" aria-label="Permalink to &quot;2. Steps to reproduce&quot;">​</a></h3><p>A numbered list a stranger could follow:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Go to /courses/.</span></span>
<span class="line"><span>2. Click &quot;Web design 101&quot;.</span></span>
<span class="line"><span>3. Click &quot;Buy now&quot;.</span></span>
<span class="line"><span>4. Pay with Stripe sandbox card 4242 4242 4242 4242.</span></span>
<span class="line"><span>5. Land back on /order/.</span></span>
<span class="line"><span>   Expected: order shows &quot;completed&quot;.</span></span>
<span class="line"><span>   Actual: order shows &quot;pending&quot; and the learner is not enrolled.</span></span></code></pre></div><h3 id="_3-expected-vs-actual" tabindex="-1">3. Expected vs actual <a class="header-anchor" href="#_3-expected-vs-actual" aria-label="Permalink to &quot;3. Expected vs actual&quot;">​</a></h3><p>What you expected to happen, what actually happened, and any error messages from <code>WP_DEBUG</code>.</p><h3 id="_4-logs" tabindex="-1">4. Logs <a class="header-anchor" href="#_4-logs" aria-label="Permalink to &quot;4. Logs&quot;">​</a></h3><p>If applicable:</p><ul><li>Browser console errors.</li><li>Network tab failed requests.</li><li><code>WP_DEBUG</code> log lines from <code>wp-content/debug.log</code>.</li><li>Sikshya activity log.</li></ul><p>Wrap in fenced code blocks. Redact license keys, gateway secrets, JWTs.</p><h3 id="_5-screenshots-videos" tabindex="-1">5. Screenshots / videos <a class="header-anchor" href="#_5-screenshots-videos" aria-label="Permalink to &quot;5. Screenshots / videos&quot;">​</a></h3><p>A 5-second screen capture of the issue is gold. Loom, CleanShot X, ShareX, or QuickTime all work.</p><h2 id="common-request-templates" tabindex="-1">Common request templates <a class="header-anchor" href="#common-request-templates" aria-label="Permalink to &quot;Common request templates&quot;">​</a></h2><h3 id="stripe-checkout-fails-for-some-learners" tabindex="-1">&quot;Stripe checkout fails for some learners&quot; <a class="header-anchor" href="#stripe-checkout-fails-for-some-learners" aria-label="Permalink to &quot;&quot;Stripe checkout fails for some learners&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Site: example.com</span></span>
<span class="line"><span>Sikshya: 1.0.3</span></span>
<span class="line"><span>Sikshya Pro: 1.0.0</span></span>
<span class="line"><span>Stripe mode: live</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What I tried:</span></span>
<span class="line"><span>- Re-tested with a sandbox card on staging — works.</span></span>
<span class="line"><span>- Re-checked the Stripe webhook secret — matches.</span></span>
<span class="line"><span>- /wp-json/sikshya/v1/webhooks/stripe is reachable from a curl POST — returns 200.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What&#39;s broken:</span></span>
<span class="line"><span>- About 1 in 8 live transactions land on /order/?failed=1.</span></span>
<span class="line"><span>- Stripe dashboard shows the payment as succeeded but the order stays pending.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Steps to reproduce: not 100% reproducible — happens on real cards in production.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Attached: 3 sample payment intent IDs from Stripe + the corresponding session_id from /sikshya/v1/checkout/session.</span></span></code></pre></div><h3 id="gradebook-page-is-blank" tabindex="-1">&quot;Gradebook page is blank&quot; <a class="header-anchor" href="#gradebook-page-is-blank" aria-label="Permalink to &quot;&quot;Gradebook page is blank&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Site: school.example.com</span></span>
<span class="line"><span>Sikshya: 1.0.3</span></span>
<span class="line"><span>Sikshya Pro: 1.0.0</span></span>
<span class="line"><span>Pro plan: Pro</span></span>
<span class="line"><span>Gradebook add-on: enabled</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What I tried:</span></span>
<span class="line"><span>- Disabled all other plugins → still blank.</span></span>
<span class="line"><span>- Switched to Twenty Twenty-Five → still blank.</span></span>
<span class="line"><span>- Browser console shows: &quot;TypeError: Cannot read properties of undefined (reading &#39;id&#39;)&quot; in /pro/gradebook/grid response.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Attached: console error stack + Network tab payload.</span></span></code></pre></div><h2 id="what-to-expect" tabindex="-1">What to expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to expect&quot;">​</a></h2><ul><li><strong>First response</strong> — within a working day for free, or per plan SLA for Pro.</li><li><strong>Triage</strong> — your report is classified (bug / question / feature / can&#39;t reproduce).</li><li><strong>Fix or workaround</strong> — bugs are routed to engineering; ETA depends on severity.</li><li><strong>Release</strong> — fixes ship in the next release. Hotfix patches when urgent.</li></ul><h2 id="escalating-a-critical-issue" tabindex="-1">Escalating a critical issue <a class="header-anchor" href="#escalating-a-critical-issue" aria-label="Permalink to &quot;Escalating a critical issue&quot;">​</a></h2><p>If a fix is blocking production revenue:</p><ol class="step-list"><li>Reply to the ticket with <strong>&quot;BLOCKING REVENUE&quot;</strong> in the subject + a quantitative impact (e.g. &quot;$5k / day&quot;).</li><li>Include a working contact (phone / WhatsApp).</li><li>We attempt a workaround within hours and a release within days.</li></ol><h2 id="feature-requests" tabindex="-1">Feature requests <a class="header-anchor" href="#feature-requests" aria-label="Permalink to &quot;Feature requests&quot;">​</a></h2><p>Welcome on:</p><ul><li><a href="https://github.com/MantraBrain" target="_blank" rel="noreferrer">GitHub issues</a> labeled <strong>enhancement</strong>.</li><li>The Facebook community.</li><li>Direct conversation with your account manager (Pro / Scale plan customers).</li></ul><p>We prioritize features that solve a problem affecting many sites, fit Sikshya&#39;s &quot;WordPress-native LMS&quot; positioning, and are reasonable to maintain long-term.</p><h2 id="security-disclosures" tabindex="-1">Security disclosures <a class="header-anchor" href="#security-disclosures" aria-label="Permalink to &quot;Security disclosures&quot;">​</a></h2><p><strong>Do not</strong> open a public GitHub issue or forum post for security vulnerabilities. Email <code>mantrabrain@gmail.com</code> privately. We follow coordinated disclosure: confirm, fix, release, then publicly credit the reporter (if desired) after the patch is in users&#39; hands.</p><h2 id="useful-links" tabindex="-1">Useful links <a class="header-anchor" href="#useful-links" aria-label="Permalink to &quot;Useful links&quot;">​</a></h2><ul><li>📖 <a href="https://docs.mantrabrain.com/sikshya-wordpress-plugin/" target="_blank" rel="noreferrer">Sikshya documentation</a> — official docs hub.</li><li>🧪 <a href="https://try.new/plugins/sikshya/" target="_blank" rel="noreferrer">Try Sikshya in Playground</a> — kick the tires without installing locally.</li><li>🛒 <a href="https://mantrabrain.com/plugins/sikshya/#pricing" target="_blank" rel="noreferrer">Buy Sikshya Pro</a> — license plans.</li><li>👥 <a href="https://www.facebook.com/groups/sikshyalms/" target="_blank" rel="noreferrer">Facebook Community</a> — peer chat.</li><li>🐙 <a href="https://github.com/MantraBrain" target="_blank" rel="noreferrer">GitHub</a> — issues and source.</li><li>📨 <a href="https://mantrabrain.com/contact/" target="_blank" rel="noreferrer">Contact Mantrabrain</a> — sales + support.</li></ul><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/plugins/sikshya/installation">Installation</a></li><li><a href="/plugins/sikshya/troubleshooting">Troubleshooting</a></li><li><a href="/plugins/sikshya/faqs">FAQs</a></li><li><a href="/plugins/sikshya/changelog">Changelog</a></li></ul>`,40)])])}const b=e(r,[["render",o]]);export{d as __pageData,b as default};
